INSERT INTO periods (period_id, period_name, start_year, end_year) VALUES
 ('PER_ARTHURIAN','Arthurian Literary Cycle (Matter of Britain)',1100,1500)
INSERT INTO sources (source_id, source_type, title, scope) VALUES
 ('SRC_GEOFFREY_MONMOUTH','primary text','Geoffrey of Monmouth, Historia Regum Britanniae (c. 1136)','Arthurian'),
 ('SRC_CHRETIEN_TROYES','primary text','Chrétien de Troyes, the Arthurian romances (c. 1170-1190)','Arthurian'),
 ('SRC_ROBERT_BORON','primary text','Robert de Boron, the Little Grail Cycle / Joseph d''Arimathie, Merlin (c. 1190-1210)','Arthurian'),
 ('SRC_VULGATE_CYCLE','primary text','The Vulgate Cycle (Lancelot-Grail) (c. 1210-1235)','Arthurian'),
 ('SRC_WOLFRAM_PARZIVAL','primary text','Wolfram von Eschenbach, Parzival (c. 1200-1210)','Arthurian'),
 ('SRC_MALORY_MORTE','primary text','Sir Thomas Malory, Le Morte d''Arthur (c. 1469-1485)','Arthurian')
INSERT INTO _e VALUES
 ('ENT_ART_ROUND_TABLE','The Knights of the Round Table','Collective','Order of chivalry','chivalry; fellowship; defense of the realm; the Grail quest','B','The fellowship of knights sworn to Arthur, gathered about the Round Table at Camelot.'),
 ('ENT_ART_ARTHUR','King Arthur','King','Legendary king','kingship; war; the Round Table; the once and future king','B','Legendary king of the Britons who founds the Round Table at Camelot and is borne to Avalon after Camlann.'),
 ('ENT_ART_GUINEVERE','Guinevere','Queen','Legendary queen','queenship; courtly love; the affair with Lancelot','B','Wife of Arthur whose love for Lancelot precipitates the fall of the realm.'),
 ('ENT_ART_UTHER_PENDRAGON','Uther Pendragon','King','Legendary king','kingship; war; the begetting of Arthur','B','King who, disguised by Merlin as Gorlois, begets Arthur upon Igraine at Tintagel.'),
 ('ENT_ART_IGRAINE','Igraine','Queen','Legendary noblewoman','noble lineage; the begetting of Arthur','B','Wife of Gorlois then Uther; mother of Arthur, Morgan, and Morgause.'),
 ('ENT_ART_MORDRED','Mordred','Knight','Legendary traitor','treachery; usurpation; the destruction of the realm','B','Begotten by Arthur upon Morgause; slays and is slain by Arthur at Camlann.'),
 ('ENT_ART_MORGAN_LE_FAY','Morgan le Fay','Enchantress','Sorceress','magic; healing; enmity toward the court','B','Magical half-sister of Arthur, both healer at Avalon and adversary of the court.'),
 ('ENT_ART_MORGAUSE','Morgause','Queen','Legendary noblewoman','queenship; the begetting of Mordred; the Orkney lineage','B','Half-sister of Arthur, wife of Lot, mother of the Orkney knights and of Mordred.'),
 ('ENT_ART_KING_LOT','King Lot','King','Legendary king','kingship; war; the Orkney lineage','B','King of Orkney, husband of Morgause and father of Gawain and his brothers.'),
 ('ENT_ART_MERLIN','Merlin','Sorcerer','Prophet-mage','magic; prophecy; counsel; the founding of the realm','B','Prophet-magician who engineers Arthur''s begetting and establishes the Round Table; in Robert de Boron, fathered by a devil and baptized.'),
 ('ENT_ART_LADY_OF_THE_LAKE','The Lady of the Lake','Enchantress','Otherworldly figure','magic; the otherworld; the giving of Excalibur','B','Otherworldly enchantress (Nimue/Viviane) who gives Excalibur, fosters Lancelot, and enchants Merlin.'),
 ('ENT_ART_LANCELOT','Lancelot','Knight','Knight of the Round Table','chivalry; prowess; courtly love; the adultery with Guinevere','B','The foremost knight, whose love for Guinevere brings the realm to ruin.'),
 ('ENT_ART_GALAHAD','Galahad','Knight','Knight of the Round Table','perfect chastity; the Grail quest; holiness','B','Son of Lancelot and Elaine of Corbenic, the sinless knight who achieves the Grail.'),
 ('ENT_ART_PERCEVAL','Perceval','Knight','Knight of the Round Table','the Grail quest; innocence; chivalric formation','B','The naive young knight (Parzival) who comes to the Grail castle; one of the Grail achievers.'),
 ('ENT_ART_GAWAIN','Gawain','Knight','Knight of the Round Table','chivalry; courtesy; kinship loyalty; the test of honor','B','Eldest son of Lot and Morgause and nephew of Arthur; tested by the Green Knight.'),
 ('ENT_ART_BORS','Bors','Knight','Knight of the Round Table','chivalry; piety; the Grail quest','B','Cousin of Lancelot and the only Grail achiever to return to Camelot.'),
 ('ENT_ART_TRISTAN','Tristan','Knight','Knight of the Round Table','chivalry; the tragic love for Isolde','B','Cornish knight whose love for Isolde parallels the Lancelot-Guinevere affair.'),
 ('ENT_ART_KAY','Kay','Knight','Knight of the Round Table','the seneschalship; blunt speech','B','Arthur''s foster-brother and seneschal, brusque but loyal.'),
 ('ENT_ART_BEDIVERE','Bedivere','Knight','Knight of the Round Table','loyalty; the return of Excalibur','B','Companion who casts Excalibur back into the lake at Arthur''s end.'),
 ('ENT_ART_GARETH','Gareth','Knight','Knight of the Round Table','chivalry; the proving of worth; kinship','B','Brother of Gawain who proves his knighthood; slain inadvertently by Lancelot.'),
 ('ENT_ART_GAHERIS','Gaheris','Knight','Knight of the Round Table','kinship; the Orkney feud; vengeance','B','Brother of Gawain who slays Morgause; later killed by Lancelot.'),
 ('ENT_ART_AGRAVAIN','Agravain','Knight','Knight of the Round Table','kinship; intrigue; the exposure of the adultery','B','Brother of Gawain who with Mordred exposes the affair, triggering the collapse.'),
 ('ENT_ART_LAMORAK','Lamorak','Knight','Knight of the Round Table','prowess; the Pellinore-Orkney feud; courtly love','B','Son of Pellinore; his affair with Morgause leads to murder by the Orkney brothers.'),
 ('ENT_ART_PELLINORE','Pellinore','King','Knight of the Round Table','kingship; the Questing Beast; the feud','B','King who pursues the Questing Beast, slays Lot, and fathers Lamorak.'),
 ('ENT_ART_GREEN_KNIGHT','The Green Knight','Legendary figure','Otherworldly challenger','the beheading game; the test of honor; the otherworld','B','Green otherworldly challenger (Bertilak enchanted) who tests Gawain''s honor in the beheading game.'),
 ('ENT_ART_FISHER_KING','The Fisher King','King','Grail guardian','guardianship of the Grail; the wasteland and its healing','B','Maimed guardian of the Grail (Pelles/Anfortas) whose wound mirrors the wasteland.'),
 ('ENT_ART_ELAINE_CORBENIC','Elaine of Corbenic','Legendary figure','Grail lineage','the Grail lineage; the conception of Galahad','B','Daughter of Pelles who conceives Galahad with Lancelot to fulfill prophecy.'),
 ('ENT_ART_ISOLDE','Isolde','Queen','Legendary lover','tragic love; the love potion; courtly devotion','B','Irish princess and queen of Cornwall, fated lover of Tristan.'),
 ('ENT_ART_ELAINE_ASTOLAT','Elaine of Astolat','Legendary figure','Legendary lover','unrequited love; tragic death','B','The lily maid of Astolat who dies of unrequited love for Lancelot.'),
 ('ENT_ART_GRAIL','The Holy Grail','Sacred object','Holy relic','divine grace; revelation; healing; the Eucharist','B','The vessel of the Last Supper brought to Britain by Joseph of Arimathea; object of the great quest.'),
 ('ENT_ART_EXCALIBUR','Excalibur','Relic','Legendary sword','kingship; war; sovereignty; the otherworld','B','Arthur''s sword (Geoffrey''s Caliburn), given by the Lady of the Lake and returned to her at his death.'),
 ('ENT_ART_ROUND_TABLE_OBJECT','The Round Table','Sacred object','Order of chivalry','fellowship; equality of the knights; the chivalric order','B','The round table made by Merlin so that no knight should sit above another.'),
 ('ENT_ART_AVALON','Avalon','cosmological realm','Otherworldly isle','the otherworld; healing; the resting place of Arthur','B','Otherworldly isle where Excalibur was forged and to which Arthur is borne to be healed.'),
 ('ENT_ART_CAMELOT','Camelot','cosmological realm','Royal seat','kingship; the chivalric court; the seat of the Round Table','B','The principal seat of Arthur''s court and of the Round Table.'),
 ('ENT_ART_SIEGE_PERILOUS','The Siege Perilous','Sacred object','Sacred seat','the Grail destiny; sanctity; predestination','B','The empty seat, fatal to the unworthy, reserved for the Grail knight Galahad.');
